/* global L */
const state={data:null,layer:null,selected:null};
const map=L.map('map',{zoomControl:false}).setView([42.45,-76.48],10);
L.control.zoom({position:'bottomright'}).addTo(map);
L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);

const $=id=>document.getElementById(id);
const riskLevel=s=>s>=.75?'very-high':s>=.5?'high':s>=.25?'moderate':'low';
const levelLabel=s=>riskLevel(s).split('-').map(w=>w[0].toUpperCase()+w.slice(1)).join(' ');
const color=s=>s>=.75?'#9f1d20':s>=.5?'#e06b35':s>=.25?'#e8bd55':'#4a9470';
const visible=f=>($('riskFilter').value==='all'||riskLevel(f.properties.risk_score)===$('riskFilter').value)&&($('habitatFilter').value==='all'||f.properties.habitat===$('habitatFilter').value);

function styleFeature(f){const show=visible(f);return{fillColor:color(f.properties.risk_score),fillOpacity:show?.78:0,opacity:show?1:0,weight:show?1:0,color:'#fff'};}
function recommendation(p){if(p.risk_score>=.75)return'Prioritize field verification and contact the relevant land manager before a planning decision.';if(p.risk_score>=.5)return'Review recent land-cover change and schedule a targeted habitat survey.';if(p.risk_score>=.25)return'Monitor the area and confirm whether the observed pressure trend continues.';return'Maintain routine monitoring; no immediate intervention is indicated by this screening score.';}
function openDetail(f){state.selected=f;const p=f.properties;$('cellName').textContent=p.cell_id+' · '+p.habitat;$('cellScore').textContent=p.risk_score.toFixed(2);$('cellLevel').textContent=levelLabel(p.risk_score);$('cellScore').style.color=color(p.risk_score);$('recommendation').textContent=recommendation(p);$('drivers').innerHTML=[['Habitat suitability',p.habitat_suitability],['Threat degradation',p.degradation],['Habitat quality',p.habitat_quality],['Road threat effect',p.road_effect],['Urban threat effect',p.urban_effect],['Agriculture threat effect',p.agriculture_effect]].map(([n,v])=>`<div class="driver"><div class="driver-head"><strong>${n}</strong><span>${v.toFixed(2)}</span></div><div class="bar"><i style="width:${v*100}%"></i></div></div>`).join('')+`<div class="driver-head"><strong>Species observations</strong><span>${p.species_count}</span></div>`;$('detailPanel').classList.add('open');}
function render(){if(state.layer)state.layer.remove();state.layer=L.geoJSON(state.data,{style:styleFeature,onEachFeature:(f,l)=>{l.on('click',()=>openDetail(f));l.bindTooltip(`<div class="popup-title">${f.properties.cell_id}</div><span class="popup-score">${f.properties.risk_score.toFixed(2)}</span> · ${levelLabel(f.properties.risk_score)}`);}}).addTo(map);const shown=state.data.features.filter(visible);const threshold=+$('threshold').value;$('areaCount').textContent=shown.length;$('highCount').textContent=shown.filter(f=>f.properties.risk_score>=threshold).length;$('avgScore').textContent=shown.length?(shown.reduce((a,f)=>a+f.properties.risk_score,0)/shown.length).toFixed(2):'--';$('mapStatus').textContent=`Showing ${shown.length} of ${state.data.features.length} cells`;$('mapStatus').hidden=false;setTimeout(()=>$('mapStatus').hidden=true,1800);}
function exportCsv(){const threshold=+$('threshold').value;const rows=state.data.features.filter(f=>visible(f)&&f.properties.risk_score>=threshold).map(f=>f.properties);const headers=['cell_id','risk_score','risk_level','habitat','habitat_suitability','degradation','habitat_quality','accessibility','road_effect','urban_effect','agriculture_effect','species_count'];const csv=[headers.join(','),...rows.map(r=>headers.map(h=>h==='risk_level'?levelLabel(r.risk_score):r[h]).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='biodiversity-priority-areas-invest.csv';a.click();URL.revokeObjectURL(a.href);}
async function init(){try{const res=await fetch('data/risk_grid.geojson');if(!res.ok)throw new Error('Data unavailable');state.data=await res.json();const habitats=[...new Set(state.data.features.map(f=>f.properties.habitat))].sort();habitats.forEach(h=>$('habitatFilter').add(new Option(h,h)));render();state.layer.eachLayer(l=>{});const bounds=state.layer.getBounds();if(bounds.isValid())map.fitBounds(bounds,{padding:[20,20]});}catch(e){$('mapStatus').textContent='Could not load the risk dataset.';console.error(e);}}
$('riskFilter').addEventListener('change',render);$('habitatFilter').addEventListener('change',render);$('threshold').addEventListener('input',e=>{$('thresholdValue').value=(+e.target.value).toFixed(2);render();});$('closeDetail').addEventListener('click',()=>$('detailPanel').classList.remove('open'));$('methodButton').addEventListener('click',()=>$('methodDialog').showModal());$('exportButton').addEventListener('click',exportCsv);
init();
